import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const SetupProfile = () => {
    const navigate = useNavigate();
    const [form, setForm] = useState({
        firstName: '',
        lastName: '',
        phone: '',
        about: ''
    });
    const [file, setFile] = useState(null);  // ✅ nou

    const handleChange = (e) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleFileChange = (e) => {       // ✅ nou
        setFile(e.target.files[0]);
    };

    const handleSubmit = async () => {
        const token = localStorage.getItem("token");

        try {
            // ✅ 1. Creare profil (fără poza)
            const res = await fetch("/profile/setup", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(form)
            });

            if (!res.ok) throw new Error("Eroare la creare profil");

            // ✅ 2. Dacă s-a selectat o poză, upload
            if (file) {
                const formData = new FormData();
                formData.append("file", file);

                await fetch("/profile/photo", {
                    method: "POST",
                    headers: {
                        Authorization: `Bearer ${token}`
                    },
                    body: formData
                });
            }

            navigate("/app/profile");
        } catch (err) {
            alert("Eroare: " + err.message);
        }
    };

    return (
        <div className="setup-profile-wrapper">
            <h2>Configurează-ți profilul</h2>
            <input name="firstName" placeholder="First Name" onChange={handleChange} />
            <input name="lastName" placeholder="Last Name" onChange={handleChange} />
            <input name="phone" placeholder="Phone" onChange={handleChange} />
            <textarea name="about" placeholder="Despre tine" onChange={handleChange} />
            <input type="file" accept="image/*" onChange={handleFileChange} />   {/* ✅ nou */}
            <button onClick={handleSubmit}>Salvează profil</button>
        </div>
    );
};

export default SetupProfile;
